CREATE TABLE public.team_working_settings(tenant_id uuid PRIMARY KEY REFERENCES public.tenants(id),default_mode text NOT NULL DEFAULT 'own' CHECK(default_mode IN ('own','across','central')),role_modes jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(role_modes)='object'),updated_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.team_working_settings TO authenticated;
GRANT ALL ON public.team_working_settings TO service_role;
ALTER TABLE public.team_working_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_working_read ON public.team_working_settings FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE FUNCTION public.save_team_working_settings(t uuid,p jsonb,expected jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old jsonb; item record; BEGIN
IF auth.uid() IS NULL OR NOT public.user_has_tenant(auth.uid(),t) OR NOT (public.people_owner(t,auth.uid()) OR public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Business settings administrator required'; END IF;
IF p->>'default_mode' IS NULL OR p->>'default_mode' NOT IN ('own','across','central') OR jsonb_typeof(p->'role_modes') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Choose a valid company default and role settings';END IF;
FOR item IN SELECT key,value FROM jsonb_each_text(p->'role_modes') LOOP IF item.value NOT IN ('own','across','central') OR NOT (item.key IN ('Bar','Floor','Kitchen','Promotions','Management','Cleaning','No role set') OR EXISTS(SELECT 1 FROM public.hr_role_groups WHERE tenant_id=t AND name=item.key)) THEN RAISE EXCEPTION 'Unknown role or team mode';END IF;END LOOP;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||'team_working_settings',0));SELECT to_jsonb(s) INTO old FROM public.team_working_settings s WHERE tenant_id=t FOR UPDATE;
IF old IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Team settings changed; review the latest choice';END IF;
INSERT INTO public.team_working_settings(tenant_id,default_mode,role_modes,updated_by) VALUES(t,p->>'default_mode',p->'role_modes',auth.uid()) ON CONFLICT(tenant_id) DO UPDATE SET default_mode=EXCLUDED.default_mode,role_modes=EXCLUDED.role_modes,updated_by=auth.uid(),updated_at=now();
INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'update','team_working_settings',t::text,jsonb_build_object('before',old,'after',p));END $$;
REVOKE ALL ON FUNCTION public.save_team_working_settings(uuid,jsonb,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_team_working_settings(uuid,jsonb,jsonb) TO authenticated;
DO $$ DECLARE def text;anchor text:='ELSIF op=''role_group'' THEN'; BEGIN SELECT pg_get_functiondef('public.bani_people_execute(uuid,uuid,text)'::regprocedure) INTO def; IF position(anchor in def)=0 THEN RAISE EXCEPTION 'People action anchor missing';END IF;def:=replace(def,anchor,'ELSIF op=''team_working'' THEN PERFORM public.save_team_working_settings(t,p->''setting'',p->''before'');result:=jsonb_build_object(''ok'',true,''message'',''Saved — How your team works updated.'',''link'',''/settings?tab=business'',''undo_available'',false); '||anchor);EXECUTE def;END $$;